        # Update max values
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update min values
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # The maximum product can be either max1 * max2 or min1 * min2
    return (max1, max2) if max1 * max2 > min1 * min2 else (min1, min2)
